// Ratgeber: Kommunale Beteiligung nach § 6 EEG in der Praxis – Empfänger, Erstattung, Vertrag,
// Haushalt, Landesgesetze, Gewerbesteuer. Recherchestand 29.09.2026: EEG 2023 § 6; GewStG § 29;
// BbgEESG vom 27.11.2025; BüGembeteilG M-V vom 23.04.2026 (GVOBl. M-V 2026 Nr. 12);
// FA Wind und Solar (Übersicht Landesregelungen PV, Stand 17.07.2026; Kommunalbefragung § 6 EEG).
// Rechenbeispiel mit dem Rechenkern des Kommunal-Rechners (src/lib/rechner/kommune.js).

import { KOMMUNE, ERLOESE, STAND } from "@/lib/invest/markt";
import { rechneKommune } from "@/lib/rechner/kommune";
import { fmt, fmtEur, fmtPct, fmtCt } from "@/lib/rechner/annahmen";

/* ------------------------------------------------------------------ */
/* Werte, die (noch) nicht in markt.js stehen – Vorschlag zur Übernahme */
/* ------------------------------------------------------------------ */

// BbgEESG vom 27.11.2025, § 2 Abs. 2 Nr. 3: Sonderabgabe PV-Freifläche > 1 MW, Inbetriebnahme nach 31.12.2024
const BB_EUR_PRO_MW = 2000;
// BüGembeteilG M-V vom 23.04.2026, § 8 Abs. 2 und § 11: Angebot je volles MW und Jahr (Gemeinde / Einwohner) bzw. Ersatzzahlung
const MV_GEMEINDE_EUR_PRO_MW = 1000;
const MV_EINWOHNER_EUR_PRO_MW = 1000;
const MV_ERSATZ_EUR_PRO_MW = 2000;
// Landesgesetze gelten jeweils erst ab 1 MW installierter Leistung (BbgEESG § 1 Abs. 3; BüGembeteilG M-V § 1 Abs. 2)
const LAND_SCHWELLE_MW = 1;
// FA Wind und Solar, Kommunalbefragung § 6 EEG (forsa, 1.655 Befragte; Windenergie): Anteile der Bürgermeister
const FA_BEFRAGUNG = { bekannt: 0.85, erstattungUnbekannt: 0.42, zufriedenUmsetzung: 0.26 };

/* ------------------------------------------------------------------ */
/* Rechenbeispiel mit dem Kommunal-Rechner                             */
/* ------------------------------------------------------------------ */

const MWP = 10;
        {
          typ: "p",
          text: "**Das Geld aus § 6 EEG ist eine allgemeine Einnahme der Gemeinde und nach Bundesrecht nicht zweckgebunden.** Laut den FAQ der FA Wind und Solar kann es grundsätzlich auch zur Schuldentilgung verwendet werden. Zweckbindungen können sich aber aus Landesrecht ergeben.",
        },
        {
          typ: "liste",
          punkte: [
            "**Gemeinderatsbeschluss:** Abschluss und Annahme erfolgen in der Regel durch Beschluss des Gemeinderats. Mitglieder, die selbst Flächen verpachten oder am Projekt beteiligt sind, können nach der jeweiligen Kommunalordnung befangen sein.",
            "**Haushaltsplanung:** Die Zahlungen schwanken mit Ertrag und Erstattungsfähigkeit. Planen Sie vorsichtig und nicht mit dem Maximalwert.",
            "**Transparenz:** Viele Gemeinden machen die Verwendung öffentlich, etwa für Vereine, Dorfgemeinschaftshaus oder Energieprojekte – das stärkt die Akzeptanz.",
            "**Finanzausgleich und Kreisumlage:** Wie solche Einnahmen im kommunalen Finanzausgleich des Landes behandelt werden, sollte die Kämmerei mit der Kommunalaufsicht klären.",
          ],
        },
        {
          typ: "kasten",
          variant: "info",
          titel: "Was die Kommunalbefragung zeigt",
          text: `In der repräsentativen Befragung der FA Wind und Solar (forsa, zur Windenergie) kannten ${fmtPct(FA_BEFRAGUNG.bekannt, 0)} der Bürgermeisterinnen und Bürgermeister die Regelung, aber ${fmtPct(FA_BEFRAGUNG.erstattungUnbekannt, 0)} wussten nichts von der Erstattungsfähigkeit. Mit der Umsetzung zufrieden waren nur ${fmtPct(FA_BEFRAGUNG.zufriedenUmsetzung, 0)} – vor allem wegen der Freiwilligkeit. 
        },
      ],
    },
    {
      id: "laender",
      titel: "Landesgesetze: Wo die Beteiligung Pflicht ist",
      tocLabel: "Landesgesetze",
      bloecke: [
        {
          typ: "p",
          text: "**Weil der Bund § 6 EEG nach einem Rechtsgutachten des BMWK nicht verpflichtend machen kann, haben mehrere Länder eigene Beteiligungsgesetze erlassen – mit sehr unterschiedlicher Höhe und Systematik.** Laut Übersicht der FA Wind und Solar (Stand Juli 2026) gibt es für Freiflächen-PV Regelungen unter anderem in Bayern, Brandenburg, Mecklenburg-Vorpommern, Niedersachsen, im Saarland, in Sachsen
        },
        {
          typ: "tabelle",
          caption: `Beispiele für Landesregelungen bei Freiflächen-PV, Stand ${STAND}`,
          kopf: ["Land", "Gesetz", "Pflicht", "Verhältnis zu § 6 EEG"],
          zeilen: [
            ["Brandenburg", "BbgEESG vom 27.11.2025 (zuvor BbgPVAbgG)", `Sonderabgabe **${fmt(BB_EUR_PRO_MW)} € je MW und Jahr** an die Standortgemeinde, Anlagen über ${LAND_SCHWELLE_MW} MW mit Inbetriebnahme ab 2025; Mittel zweckgebunden für Akzeptanzmaßnahmen`, "eigenständige Abgabe; nach FA-Übersicht keine Anrechnung"],
            ["Mecklenburg-Vorpommern", "BüGembeteilG M-V vom 23.04.2026", `Angebot von **${fmt(MV_GEMEINDE_EUR_PRO_MW)} € je MW** für die Gemeinde und **${fmt(MV_EINWOHNER_EUR_PRO_MW)} € je MW** für Einwohner (Gutschrift oder Direktzahlung) ab ${LAND_SCHWELLE_MW} MW; ohne Einigung Ersatzzahlung ${fmt(MV_ERSATZ_EUR_PRO_MW)} € je MW`, "§ 6-Zahlungen können nach § 3 Abs. 8 angerechnet werden"],
            ["Niedersachsen", "NWindPVBetG (2024)", "Akzeptanzabgabe 0,2 ct/kWh an die Gemeinde, zusätzlich Angebot einer Beteiligung der Bevölkerung (im Mittel 0,1 ct/kWh)", "Anrechnung möglich"],
            ["Übrige Länder", "keine Solarregelung oder in Vorbereitung", "freiwillige Zahlung nach § 6 EEG", "–"],
          ],
          hervorheben: 2,
          minBreite: 760,
          fussnote: "MV: gilt für Freiflächenanlagen, deren Aufstellungsbeschluss nach Inkrafttreten (29.04.2026) gefasst wird; Bürgerenergiegesellschaften und besondere Solaranlagen wie Agri-PV und Moor-PV sind ausgenommen. BB: Anlagen bis einschließlich 1 MW sind befreit. Details der übrigen Länder laut FA Wind und Solar; maßgeblich sind die jeweiligen Gesetzestexte.",
        },
        {
          typ: "p",
          text: `Zur Größenordnung für ${MWP} MWp: In Brandenburg kämen zur freiwilligen § 6-Zahlung von rund ${fmtEur(P6_JAHR)} weitere ${fmtEur(BB_JAHR)} Sonderabgabe hinzu. In Mecklenburg-Vorpommern müssen insgesamt ${fmtEur(MV_JAHR)} im Jahr angeboten werden, auf die § 6-Zahlungen angerechnet werden können. Dass [besondere Solaranlagen](/wissen/lexikon#besondere-solaranlagen) wie Agri-PV und Anlagen von [
        },
      ],
    },
    {
106:            ["Burgenland", "Widmung „Grünfläche-Photovoltaik“ oberhalb kleiner Bagatellgrenzen", "Widmung nur **innerhalb verordneter Eignungszonen**; Zonen-Mindestgröße grundsätzlich 10 ha", "Agri-PV oder extensive Grünlandnutzung in Zonen mit hoher Bodengüte verpflichtend; jährlich
238:            "**Landesabgaben übersehen:** Das Burgenland erhebt eine jährliche Photovoltaikabgabe je Megawatt installierter Leistung (§ 22e Bgld. RPG); sie gehört in jede Kalkulation.",

},
{
  titel: "Photovoltaikabgabe je Megawatt",
  text: "Als Ausgleich für die Belastung des Landschaftsbildes erhebt das Land eine jährliche **Photovoltaikabgabe**, bemessen nach der installierten Leistung (Euro je Megawatt), nicht nach der Fläche. Der Grundbetrag steht in der Verordnung über die Bemessungsgrundlage und wird marktpreisabhängig erhöht, für 2025 etwa um 36,61 %. Ein fester Anteil je Megawatt fließt der Standortgemeinde zu, der Rest dem Klima- und Sozialfonds des Landes. Abgabepflichtig ist der Inhaber der Genehmigung, also in der Regel der Betreiber – nicht der Verpächter.",
  quelle: { titel: "RIS – Bgld. RPG 2019 § 22e und VO Bemessungsgrundlage Windkraft- und Photovoltaikabgabe", url: "https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=LrBgld&Gesetzesnummer=20001418" },
},
{
  titel: "Elektrizitätsrecht: Genehmigung über 500 kWp",
  text: "Nach § 5 des Burgenländischen Elektrizitätswesengesetzes 2006 bedürfen Photovoltaikanlagen mit mehr als 500 kWpeak einer elektrizitätsrechtlichen Anlagengenehmigung, Energiespeicher ab mehr als 1 MWh Kapazität ebenso.",
